  bool PlainForwardSupportForCast(float distance){
   // Conservative input policy, not a claim that native skill displacement is
   // exactly this length. Avoid a known large forced-movement skill near ledges.
   if(!game.Grounded(game.player)||game.CurrentRoom.surfaces==null)return false;
   foreach(var support in game.CurrentRoom.surfaces)if(support.id==game.player.groundLine){
    float end=game.player.x+game.player.facing*distance;
    return game.player.x>=support.x1+12&&game.player.x<=support.x2-12&&end>=support.x1+12&&end<=support.x2-12&&Math.Abs(support.Y(end)-support.Y(game.player.x))<=8;
   }
   return false;
  }
